import type { ZodTypeAny, infer as ZodInfer } from 'zod';
import { formatZodErrors } from './errors';

export type ParseJsonResult<T> =
  | { ok: true; data: T }
  | {
      ok: false;
      code: 'INVALID_JSON' | 'VALIDATION_ERROR' | 'PAYLOAD_TOO_LARGE' | 'JSON_KEY_RESTRICTED';
      error: string;
      fields?: Record<string, string>;
    };

/**
 * Default request-body cap. Cloudflare Workers allow up to 100 MB but
 * application bodies that large are almost always either a misconfigured
 * client or an attempted resource-exhaustion abuse — list/batch routes
 * fan out per-record and a 100 MB body materialised into per-record loops
 * is genuinely dangerous. 1 MiB is generous for any realistic JSON payload
 * and matches the default many frameworks ship.
 */
const DEFAULT_MAX_BODY_BYTES = 1024 * 1024;

export type ReadJsonResult =
  | { ok: true; data: unknown }
  | { ok: false; code: 'INVALID_JSON' | 'PAYLOAD_TOO_LARGE'; error: string };

/**
 * Read and JSON-parse a request body, without schema validation.
 *
 * Enforces a body size cap before parsing — the cap is read first from
 * the Content-Length header, then (defensively) by streaming the body
 * with a running byte counter. Either over-limit signal returns 413
 * `PAYLOAD_TOO_LARGE` rather than crashing the parser or stalling the
 * route on a hostile body.
 */
export async function readJsonBody(
  request: Request,
  options: { maxBodyBytes?: number } = {},
): Promise<ReadJsonResult> {
  const maxBytes = options.maxBodyBytes ?? DEFAULT_MAX_BODY_BYTES;

  // Cheap path: trust the client-declared Content-Length. Some clients
  // omit it (chunked / streaming); the read-loop below catches those.
  if (declaredLengthExceeds(request, maxBytes)) {
    return {
      ok: false,
      code: 'PAYLOAD_TOO_LARGE',
      error: `Request body exceeds ${maxBytes} byte limit.`,
    };
  }

  let raw: string;
  try {
    raw = await readBoundedText(request, maxBytes);
  } catch (err: any) {
    if (isPayloadTooLarge(err)) {
      return {
        ok: false,
        code: 'PAYLOAD_TOO_LARGE',
        error: `Request body exceeds ${maxBytes} byte limit.`,
      };
    }
    return {
      ok: false,
      code: 'INVALID_JSON',
      error: 'Request body must be valid JSON.',
    };
  }

  try {
    return { ok: true, data: raw.length === 0 ? undefined : JSON.parse(raw) };
  } catch {
    return {
      ok: false,
      code: 'INVALID_JSON',
      error: 'Request body must be valid JSON.',
    };
  }
}

/** Validate an already-parsed body against a Zod schema. */
export function validateWithSchema<TSchema extends ZodTypeAny>(
  body: unknown,
  schema: TSchema,
): ParseJsonResult<ZodInfer<TSchema>> {
  const parsed = schema.safeParse(body);
  if (!parsed.success) {
    // q.json(schema, { keys }): a platform-managed key in the body is a 422
    // JSON_KEY_RESTRICTED, not a shape error (see jsonKeyRestrictionRefine).
    const restricted = parsed.error.issues.filter((i: any) => i.code === 'custom' && i.params?.qbJsonKeyRestricted === true);
    if (restricted.length > 0) {
      return {
        ok: false,
        code: 'JSON_KEY_RESTRICTED',
        error: 'Platform-managed JSON key(s) cannot be written here.',
        fields: formatZodErrors(restricted),
      };
    }
    return {
      ok: false,
      code: 'VALIDATION_ERROR',
      error: 'Request body validation failed.',
      fields: formatZodErrors(parsed.error.issues),
    };
  }
  return { ok: true, data: parsed.data };
}

/**
 * Parse request JSON and validate against a Zod schema — `readJsonBody`
 * then `validateWithSchema`. Returns structured errors suitable for
 * deterministic 400 / 413 responses.
 */
export async function parseJsonWithSchema<TSchema extends ZodTypeAny>(
  request: Request,
  schema: TSchema,
  options: { maxBodyBytes?: number } = {},
): Promise<ParseJsonResult<ZodInfer<TSchema>>> {
  const read = await readJsonBody(request, options);
  return read.ok ? validateWithSchema(read.data, schema) : read;
}

/**
 * The part of a RAW body the guards layer judges: its keys that name a
 * column (all keys when `columns` is null). Guards run on this BEFORE the
 * strict body schema — that schema omits every guarded key, so parsing
 * first would turn each GUARD_* rejection into VALIDATION_ERROR
 * "Unrecognized field". Keys naming no column are left to the schema's own
 * unknown-key error. Returns null for anything but a plain object: arrays,
 * null and primitives fall through to the schema's type error.
 */
export function guardView(
  body: unknown,
  columns: ReadonlySet<string> | null,
): Record<string, any> | null {
  if (body === null || typeof body !== 'object' || Array.isArray(body)) return null;
  const view: Record<string, any> = {};
  for (const [key, value] of Object.entries(body)) {
    if (!columns || columns.has(key)) view[key] = value;
  }
  return view;
}

/**
 * Batch twin of `guardView`: judges each `records[i]` of a RAW batch
 * body with `check` (the guard error, or null). A rejected record is
 * returned by index for the handler's per-record `errors`, and — in the
 * returned `input` — loses the column keys `recordSchema` doesn't accept,
 * so the strict envelope parse cannot also fail the WHOLE request over the
 * keys the guard already reported. Its remaining keys still meet the schema.
 */
export function guardBatchRecords(
  body: unknown,
  columns: ReadonlySet<string>,
  recordSchema: { shape: object },
  check: (input: Record<string, any>) => unknown,
): { input: unknown; rejected: Map<number, { record: unknown; error: any }> } {
  const rejected = new Map<number, { record: unknown; error: any }>();
  const records = (body as { records?: unknown } | null | undefined)?.records;
  if (!Array.isArray(records)) return { input: body, rejected };
  const accepted = (key: string) => !columns.has(key) || Object.prototype.hasOwnProperty.call(recordSchema.shape, key);
  const judged = records.map((record, index) => {
    const view = guardView(record, columns);
    const error = view ? check(view) : null;
    if (!error) return record;
    rejected.set(index, { record, error });
    return Object.fromEntries(Object.entries(record as object).filter(([key]) => accepted(key)));
  });
  return { input: { ...(body as object), records: judged }, rejected };
}

/**
 * True when `error` is the tagged over-limit error thrown by the bounded
 * readers. Lets callers answer 413 without string-matching a message.
 */
export function isPayloadTooLarge(error: unknown): boolean {
  return !!error && (error as { code?: string }).code === 'PAYLOAD_TOO_LARGE';
}

/**
 * Reject early when the client declares an over-limit body. Cheap, but
 * advisory only: `Content-Length` is absent on chunked/streamed requests and
 * a hostile client can simply understate it, so every caller must still read
 * through a bounded reader. Never treat a passing check here as proof of size.
 */
export function declaredLengthExceeds(request: Request, maxBytes: number): boolean {
  const declared = request.headers.get('content-length');
  if (!declared) return false;
  const n = Number(declared);
  return Number.isFinite(n) && n > maxBytes;
}

export async function readBoundedText(request: Request, maxBytes: number): Promise<string> {
  // Stream the body so we can short-circuit the moment we exceed the
  // limit, instead of buffering the whole thing into memory first.
  // Workers / undici give us a ReadableStream of Uint8Array chunks.
  const body = request.body;
  if (!body) return '';
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let total = 0;
  let out = '';
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      if (value) {
        total += value.byteLength;
        if (total > maxBytes) {
          // Throw a tagged error so the caller can map to PAYLOAD_TOO_LARGE.
          const err: any = new Error('payload too large');
          err.code = 'PAYLOAD_TOO_LARGE';
          throw err;
        }
        out += decoder.decode(value, { stream: true });
      }
    }
    out += decoder.decode();
  } finally {
    try { reader.releaseLock(); } catch { /* ignore */ }
  }
  return out;
}

/**
 * Binary counterpart of `readBoundedText` — for uploads, where the body is
 * bytes rather than text and the limit is the bucket's own file-size cap.
 *
 * Aborts at the first chunk that crosses `maxBytes`, so an omitted or
 * understated `Content-Length` cannot get more than one chunk past the limit.
 * Throws the same tagged `PAYLOAD_TOO_LARGE` error.
 */
export async function readBoundedBytes(request: Request, maxBytes: number): Promise<Uint8Array> {
  const body = request.body;
  if (!body) return new Uint8Array(0);
  const reader = body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      if (value) {
        total += value.byteLength;
        if (total > maxBytes) {
          const err: any = new Error('payload too large');
          err.code = 'PAYLOAD_TOO_LARGE';
          throw err;
        }
        chunks.push(value);
      }
    }
  } finally {
    try { reader.releaseLock(); } catch { /* ignore */ }
  }
  const out = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return out;
}

